"""
Sri Lanka Travel - one-click installer.
HOW TO USE:
  1. Put this file in your project folder (the one that has manage.py).
  2. In the terminal run:   python install_site.py
  3. Press Ctrl+F5 in the browser.
Old files are saved as .bak before they are replaced.
"""
import os, shutil, sys

if not os.path.exists("manage.py") or not os.path.isdir("blog"):
    sys.exit("STOP: run this file from the folder that contains manage.py and the blog folder.")

FILES = {
 "blog/urls.py": "from django.urls import path\n\nfrom . import views\n\nurlpatterns = [\n    path(\"\", views.post_list, name=\"home\"),\n    path(\"posts/<slug:slug>/\", views.post_detail, name=\"post_detail\"),\n    path(\"about/\", views.about, name=\"about\"),\n    path(\"contact/\", views.contact, name=\"contact\"),\n    # new: pages opened from the chart bars\n    path(\"destination/<slug:slug>/\", views.destination, name=\"destination\"),\n    # new: live data for JavaScript\n    path(\"api/live/\", views.live_data),\n    path(\"api/live/<slug:slug>/\", views.destination_live),\n    path(\"api/online/\", views.online),\n]\n",
 "blog/views.py": "import random\nimport time\n\nfrom django.core.cache import cache\nfrom django.core.paginator import Paginator\nfrom django.http import Http404, JsonResponse\nfrom django.shortcuts import get_object_or_404, render\n\nfrom .models import Post\n\nDESTINATIONS = {\n    \"beaches\": {\"name\": \"Beaches\", \"emoji\": \"🏖️\", \"photo\": \"images/photo1.jpg\", \"best\": \"November to April (south and west coast)\",\n                \"text\": \"Golden sand, surf and sunsets. Mirissa for whale watching, Unawatuna for calm water, Arugam Bay for surfing.\"},\n    \"mountains\": {\"name\": \"Mountains\", \"emoji\": \"⛰️\", \"photo\": \"images/photo2.jpg\", \"best\": \"January to April\",\n                  \"text\": \"Tea hills, waterfalls and misty trails. Ride the train to Ella and hike Little Adam's Peak.\"},\n    \"wildlife\": {\"name\": \"Wildlife\", \"emoji\": \"🐘\", \"photo\": \"images/photo3.jpg\", \"best\": \"February to July (Yala)\",\n                 \"text\": \"Leopards in Yala, elephants in Udawalawe and Minneriya, and blue whales off the south coast.\"},\n    \"culture\": {\"name\": \"Culture\", \"emoji\": \"🛕\", \"photo\": \"images/photo4.jpg\", \"best\": \"January to April\",\n                \"text\": \"Climb Sigiriya, visit the Temple of the Tooth in Kandy and explore ancient Anuradhapura.\"},\n    \"food\": {\"name\": \"Food\", \"emoji\": \"🍛\", \"photo\": \"images/photo5.jpg\", \"best\": \"All year\",\n             \"text\": \"Rice and curry, kottu roti, hoppers and fresh seafood. Try street food in Colombo.\"},\n}\nORDER = list(DESTINATIONS)\n\n\ndef post_list(request):\n    posts = Paginator(Post.objects.all().order_by(\"-id\"), 6)\n    page_obj = posts.get_page(request.GET.get(\"page\"))\n    return render(request, \"lk/home.html\", {\"page_obj\": page_obj})\n\n\ndef post_detail(request, slug):\n    post = get_object_or_404(Post, slug=slug)\n    return render(request, \"lk/post_detail.html\", {\"post\": post})\n\n\ndef about(request):\n    return render(request, \"lk/about.html\")\n\n\ndef contact(request):\n    sent = False\n    if request.method == \"POST\":\n        # Message is printed in the terminal. Later you can save it or e-mail it.\n        print(\"CONTACT:\", request.POST.get(\"name\"), request.POST.get(\"email\"), request.POST.get(\"message\"))\n        sent = True\n    return render(request, \"lk/contact.html\", {\"sent\": sent})\n\n\ndef destination(request, slug):\n    d = DESTINATIONS.get(slug)\n    if d is None:\n        raise Http404(\"Unknown destination\")\n    nxt = ORDER[(ORDER.index(slug) + 1) % len(ORDER)]\n    return render(request, \"lk/destination.html\", {\"d\": d, \"slug\": slug, \"next\": nxt})\n\n\ndef live_data(request):\n    return JsonResponse({\"values\": [random.randint(5, 100) for _ in range(5)]})\n\n\ndef destination_live(request, slug):\n    if slug not in DESTINATIONS:\n        raise Http404\n    return JsonResponse({\"value\": random.randint(5, 100)})\n\n\ndef online(request):\n    sid = request.GET.get(\"sid\", \"\")[:40]\n    users = cache.get(\"online\", {})\n    now = time.time()\n    if sid:\n        users[sid] = now\n    users = {k: v for k, v in users.items() if now - v < 15}\n    cache.set(\"online\", users, 60)\n    return JsonResponse({\"online\": len(users)})\n",
 "blog/static/lk/base.css": ":root { --g1: #064e3b; --g2: #047857; --g3: #10b981; --orange: #f59e0b; --bg: #f4f7f2; --ink: #1f2937; --mut: #6b7280; }\n* { box-sizing: border-box; margin: 0; }\nhtml { scroll-behavior: smooth; }\nbody { background: var(--bg); color: var(--ink); font-family: \"Segoe UI\", system-ui, Arial, sans-serif; line-height: 1.6; }\na { color: inherit; }\n#prog { position: fixed; top: 0; left: 0; height: 4px; width: 0; background: var(--orange); z-index: 30; }\n\nnav { position: sticky; top: 0; z-index: 20; display: flex; flex-wrap: wrap; gap: 10px; justify-content: space-between; align-items: center;\n      padding: 14px 6%; background: var(--g1); color: #fff; transition: box-shadow .3s; }\nnav.sh { box-shadow: 0 6px 24px #0004; }\n.logo { font-weight: 800; font-size: 1.25rem; text-decoration: none; color: #fff; }\n.links a { color: #fff; text-decoration: none; margin-left: 20px; padding-bottom: 3px; border-bottom: 2px solid transparent; }\n.links a:hover, .links a.act { border-color: var(--orange); }\n.pill { display: inline-block; background: #ffffff22; color: #fff; padding: 4px 12px; border-radius: 20px; font-size: .85rem; margin-left: 10px; font-variant-numeric: tabular-nums; }\n\n.wrap { max-width: 1150px; margin: 0 auto; padding: 56px 20px; }\n.title { text-align: center; color: var(--g1); font-size: 2rem; margin-bottom: 4px; }\n.sub { text-align: center; color: var(--mut); margin-bottom: 32px; }\np { margin-bottom: 10px; }\n\n.card { background: #fff; border-radius: 16px; box-shadow: 0 4px 18px #0001; overflow: hidden; transition: transform .3s, box-shadow .3s; }\n.card:hover { transform: translateY(-6px); box-shadow: 0 14px 30px #0002; }\n.cbody { padding: 18px; }\n.cbody h3 { color: var(--g1); margin-bottom: 6px; }\n.cbody p { color: var(--mut); font-size: .95rem; }\n.grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: 22px; }\n.two { display: grid; grid-template-columns: 1.4fr 1fr; gap: 22px; }\na.post { text-decoration: none; display: block; }\n.thumb { height: 170px; background: linear-gradient(135deg, var(--g2), var(--g3)); display: flex; align-items: center; justify-content: center; font-size: 3rem; }\n.thumb img { width: 100%; height: 100%; object-fit: cover; }\n.chip { display: inline-block; background: #d1fae5; color: var(--g1); font-size: .75rem; font-weight: 700; padding: 2px 10px; border-radius: 20px; margin-bottom: 8px; }\n\n.btn { display: inline-block; padding: 10px 24px; border-radius: 30px; border: 0; cursor: pointer; background: var(--g2); color: #fff; font-weight: 600; font-size: 1rem; text-decoration: none; transition: transform .2s, background .2s; }\n.btn:hover { transform: scale(1.06); background: var(--g1); }\n.btn.orange { background: var(--orange); color: #111; }\n.btn.light { background: #ffffff33; color: #fff; }\n.stat { font-size: 2rem; font-weight: 800; color: var(--g2); }\n.pulse { display: inline-block; width: 10px; height: 10px; border-radius: 50%; background: #22c55e; animation: p 1s infinite; margin-right: 8px; }\n@keyframes p { 50% { opacity: .2; } }\n\n.pager { text-align: center; margin-top: 34px; }\n.pager a, .pager span { display: inline-block; padding: 8px 16px; margin: 0 4px; border-radius: 8px; background: #fff; border: 1px solid #d1d5db; text-decoration: none; }\n.pager span { background: var(--g2); color: #fff; border-color: var(--g2); }\n\ninput, textarea { width: 100%; padding: 10px; margin: 6px 0 14px; border-radius: 10px; border: 1px solid #d1d5db; font-size: 1rem; font-family: inherit; }\ninput[type=range] { padding: 0; accent-color: var(--g2); }\n\nfooter { background: var(--g1); color: #d1fae5; text-align: center; padding: 34px 20px; margin-top: 30px; }\nfooter a { margin: 0 10px; text-decoration: none; }\n\n.reveal { opacity: 0; transform: translateY(26px); transition: opacity .7s, transform .7s; }\n.reveal.in { opacity: 1; transform: none; }\n\n@media (max-width: 800px) { .two { grid-template-columns: 1fr; } .links a { margin-left: 12px; } }\n@media (prefers-reduced-motion: reduce) { * { animation: none !important; transition: none !important; } .reveal { opacity: 1; transform: none; } }\n",
 "blog/static/lk/base.js": "const $ = id => document.getElementById(id);\n\n/* navbar shadow + top progress bar */\naddEventListener('scroll', () => {\n  $('prog').style.width = scrollY / Math.max(1, document.body.scrollHeight - innerHeight) * 100 + '%';\n  document.querySelector('nav').classList.toggle('sh', scrollY > 10);\n});\n\n/* live Sri Lanka clock */\nsetInterval(() => { $('clock').textContent = '🇱🇰 ' + new Date().toLocaleTimeString('en-GB', { timeZone: 'Asia/Colombo' }); }, 1000);\n\n/* live visitors online (asks Python every 5 seconds) */\nconst sid = Math.random().toString(36).slice(2);\nconst beat = () => fetch('/api/online/?sid=' + sid).then(r => r.json()).then(d => { $('on').textContent = d.online; if ($('on2')) $('on2').textContent = d.online; }).catch(() => {});\nbeat(); setInterval(beat, 5000);\n\n/* fade-in when scrolling */\nconst io = new IntersectionObserver(es => es.forEach(e => { if (e.isIntersecting) { e.target.classList.add('in'); io.unobserve(e.target); } }), { threshold: .12 });\ndocument.querySelectorAll('.reveal').forEach(el => io.observe(el));\n",
 "blog/templates/lk/about.html": "{% extends \"lk/base.html\" %}\n{% block title %}About – Sri Lanka Travel{% endblock %}\n{% block content %}\n<main class=\"wrap\" style=\"max-width:820px\">\n  <h2 class=\"title\">About</h2>\n  <p class=\"sub\">The story behind this blog</p>\n  <div class=\"card\"><div class=\"cbody\">\n    <p>Welcome to the Sri Lanka Travel Blog. Here we share stories, tips and photos about beaches, mountains, wildlife and culture on the island.</p>\n    <p>Write your own text here: who you are, why you travel and what readers can find on this site.</p>\n  </div></div>\n</main>\n{% endblock %}\n",
 "blog/templates/lk/base.html": "{% load static %}\n<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>{% block title %}Sri Lanka Travel{% endblock %}</title>\n<link rel=\"stylesheet\" href=\"{% static 'lk/base.css' %}\">\n{% block head %}{% endblock %}\n</head>\n<body>\n<div id=\"prog\"></div>\n\n<nav>\n  <a class=\"logo\" href=\"{% url 'home' %}\">🌴 LK Sri Lanka Travel</a>\n  <div class=\"links\">\n    <a href=\"{% url 'home' %}\" class=\"{% if request.resolver_match.url_name == 'home' %}act{% endif %}\">Home</a>\n    <a href=\"{% url 'about' %}\" class=\"{% if request.resolver_match.url_name == 'about' %}act{% endif %}\">About</a>\n    <a href=\"{% url 'contact' %}\" class=\"{% if request.resolver_match.url_name == 'contact' %}act{% endif %}\">Contact</a>\n    <span class=\"pill\" id=\"clock\">--:--:--</span><span class=\"pill\">● <span id=\"on\">1</span> online</span>\n  </div>\n</nav>\n\n{% block content %}{% endblock %}\n\n<footer>\n  <p><a href=\"{% url 'home' %}\">Home</a><a href=\"{% url 'about' %}\">About</a><a href=\"{% url 'contact' %}\">Contact</a></p>\n  <p>© 2026 Sri Lanka Travel Blog</p>\n</footer>\n\n<script src=\"{% static 'lk/base.js' %}\"></script>\n{% block scripts %}{% endblock %}\n</body>\n</html>\n",
 "blog/templates/lk/contact.html": "{% extends \"lk/base.html\" %}\n{% block title %}Contact – Sri Lanka Travel{% endblock %}\n{% block content %}\n<main class=\"wrap\" style=\"max-width:640px\">\n  <h2 class=\"title\">Contact</h2>\n  <p class=\"sub\">Send us a message</p>\n  <div class=\"card\"><div class=\"cbody\">\n    {% if sent %}\n      <div class=\"stat\">Thank you! 🌴</div><p>Your message was received.</p>\n    {% else %}\n      <form method=\"post\">{% csrf_token %}\n        <label>Name</label><input name=\"name\" required>\n        <label>Email</label><input name=\"email\" type=\"email\" required>\n        <label>Message</label><textarea name=\"message\" rows=\"5\" required></textarea>\n        <button class=\"btn\" type=\"submit\">Send</button>\n      </form>\n    {% endif %}\n  </div></div>\n</main>\n{% endblock %}\n",
 "blog/templates/lk/destination.html": "{% extends \"lk/base.html\" %}\n{% load static %}\n{% block title %}{{ d.name }} – Sri Lanka Travel{% endblock %}\n{% block head %}\n<style>\n  .dhero { height: 42vh; min-height: 260px; background: url(\"{% static d.photo %}\") center/cover; position: relative; display: flex; align-items: flex-end; color: #fff; }\n  .dhero::after { content: \"\"; position: absolute; inset: 0; background: linear-gradient(#064e3b33, #064e3bcc); }\n  .dhero h1 { position: relative; z-index: 1; font-size: clamp(2.4rem, 8vw, 4.5rem); padding: 0 6% 26px; text-shadow: 0 4px 20px #0008; }\n  #dl { width: 100%; height: 160px; display: block; }\n</style>\n{% endblock %}\n{% block content %}\n<header class=\"dhero\"><h1>{{ d.emoji }} {{ d.name }}</h1></header>\n<main class=\"wrap\">\n  <p>{{ d.text }}</p>\n  <p>Best time to go: <b>{{ d.best }}</b></p>\n  <a class=\"btn\" href=\"{% url 'home' %}\">← Back to home</a>\n  <a class=\"btn orange\" href=\"{% url 'destination' next %}\">Next place →</a>\n  <div class=\"two\" style=\"margin-top:22px\">\n    <div class=\"card\"><div class=\"cbody\"><div style=\"margin-bottom:6px\"><span class=\"pulse\"></span>Live interest: <b id=\"now\">0</b></div><canvas id=\"dl\"></canvas></div></div>\n    <div class=\"card\"><div class=\"cbody\"><h3>Plan this trip</h3>\n      <label>Days: <b id=\"dv\">5</b></label><input type=\"range\" id=\"days\" min=\"1\" max=\"21\" value=\"5\">\n      <label>USD per day: <b id=\"bv\">80</b></label><input type=\"range\" id=\"bud\" min=\"20\" max=\"300\" step=\"10\" value=\"80\">\n      <div>Total estimate</div><div class=\"stat\" id=\"tt\">$400</div></div></div>\n  </div>\n</main>\n{% endblock %}\n{% block scripts %}\n<script>\nconst hs = [], c = $('dl'), x = c.getContext('2d');\nasync function tick() {\n  let v;\n  try { v = (await (await fetch('/api/live/{{ slug }}/')).json()).value; } catch { v = Math.floor(Math.random() * 95) + 5; }\n  hs.push(v); if (hs.length > 40) hs.shift(); $('now').textContent = v;\n  c.width = c.clientWidth * 2; c.height = c.clientHeight * 2; x.lineWidth = 5; x.strokeStyle = '#047857'; x.beginPath();\n  const m = Math.max(...hs, 1), st = c.width / 39;\n  hs.forEach((h, i) => { const px = i * st, py = c.height - h / m * (c.height - 20) - 10; i ? x.lineTo(px, py) : x.moveTo(px, py); }); x.stroke();\n}\ntick(); setInterval(tick, 1000);\nconst calc = () => { $('dv').textContent = $('days').value; $('bv').textContent = $('bud').value; $('tt').textContent = '$' + ($('days').value * $('bud').value).toLocaleString(); };\n$('days').oninput = calc; $('bud').oninput = calc;\n</script>\n{% endblock %}\n",
 "blog/templates/lk/home.html": "{% extends \"lk/base.html\" %}\n{% load static %}\n{% block title %}Sri Lanka Travel{% endblock %}\n{% block head %}\n<style>\n  .hero { position: relative; height: 78vh; min-height: 420px; overflow: hidden; color: #fff; display: flex; align-items: center; justify-content: center; text-align: center; }\n  .slide { position: absolute; inset: 0; opacity: 0; transition: opacity 1.6s; background-size: cover; background-position: center; }\n  .slide.on { opacity: 1; }\n  .hero::after { content: \"\"; position: absolute; inset: 0; background: linear-gradient(#064e3bcc, #064e3b88); }\n  .hero .in { position: relative; z-index: 2; padding: 0 20px; }\n  .hero h1 { font-size: clamp(2.4rem, 8vw, 5rem); text-shadow: 0 4px 20px #0007; }\n  .hero h1 small { font-size: .4em; background: var(--orange); color: #111; padding: 2px 10px; border-radius: 8px; vertical-align: middle; }\n  .hero p { font-size: 1.25rem; margin: 10px 0 24px; min-height: 1.6em; }\n  .hero .btn { margin: 0 6px 8px; }\n  .strip { display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 16px; max-width: 1000px; margin: -50px auto 0; padding: 0 20px; position: relative; z-index: 5; }\n  .strip .card { text-align: center; padding: 18px 10px; }\n  .strip small { color: var(--mut); }\n  .bars { display: flex; align-items: flex-end; gap: 12px; height: 220px; padding: 0 6px; }\n  .bar { flex: 1; text-align: center; font-size: .8rem; cursor: pointer; }\n  .bar div { border-radius: 10px 10px 0 0; transition: height .8s; padding-top: 4px; font-weight: bold; color: #fff; }\n  #line { width: 100%; height: 150px; display: block; }\n</style>\n{% endblock %}\n{% block content %}\n<header class=\"hero\">\n  <div class=\"slide on\" style=\"background-image:url('{% static 'images/photo1.jpg' %}')\"></div>\n  <div class=\"slide\" style=\"background-image:url('{% static 'images/photo2.jpg' %}')\"></div>\n  <div class=\"slide\" style=\"background-image:url('{% static 'images/photo3.jpg' %}')\"></div>\n  <div class=\"slide\" style=\"background-image:url('{% static 'images/photo4.jpg' %}')\"></div>\n  <div class=\"slide\" style=\"background-image:url('{% static 'images/photo5.jpg' %}')\"></div>\n  <div class=\"in\">\n    <h1>Discover Sri Lanka <small>LK</small></h1>\n    <p id=\"typed\"></p>\n    <a class=\"btn orange\" href=\"#stories\">Explore Stories</a>\n    <a class=\"btn light\" href=\"#live\">Live dashboard</a>\n  </div>\n</header>\n\n<div class=\"strip\">\n  <div class=\"card\"><div class=\"stat\">{{ page_obj.paginator.count }}</div><small>Travel stories</small></div>\n  <div class=\"card\"><div class=\"stat\" id=\"on2\">1</div><small>Visitors online</small></div>\n  <div class=\"card\"><div class=\"stat\">5</div><small>Places to explore</small></div>\n  <div class=\"card\"><div class=\"stat\" id=\"sec\">0</div><small>Seconds on page</small></div>\n</div>\n\n<section class=\"wrap\" id=\"stories\">\n  <h2 class=\"title\">Latest Travel Stories</h2>\n  <p class=\"sub\">Discover beautiful places around Sri Lanka</p>\n  <div class=\"grid\">\n    {% for p in page_obj %}\n    <a class=\"card post reveal\" href=\"{% url 'post_detail' p.slug %}\">\n      <div class=\"thumb\">{% if p.image %}<img src=\"{{ p.image.url }}\" alt=\"\">{% else %}🌴{% endif %}</div>\n      <div class=\"cbody\">\n        {% if p.category %}<span class=\"chip\">{{ p.category }}</span>{% endif %}\n        <h3>{{ p.title }}</h3>\n        <p>{{ p.content|truncatewords:18 }}</p>\n        <span class=\"btn\" style=\"margin-top:8px\">Read More →</span>\n      </div>\n    </a>\n    {% empty %}<div class=\"card\"><div class=\"cbody\">No stories yet. Add posts in the admin.</div></div>{% endfor %}\n  </div>\n  <div class=\"pager\">\n    {% if page_obj.has_previous %}<a href=\"?page={{ page_obj.previous_page_number }}#stories\">← Prev</a>{% endif %}\n    <span>{{ page_obj.number }}</span>\n    {% if page_obj.has_next %}<a href=\"?page={{ page_obj.next_page_number }}#stories\">Next →</a>{% endif %}\n  </div>\n</section>\n\n<section class=\"wrap\" id=\"live\" style=\"padding-top:0\">\n  <h2 class=\"title\"><span class=\"pulse\"></span>Live interest</h2>\n  <p class=\"sub\">Click a bar to open that place</p>\n  <div class=\"two\">\n    <div class=\"card\"><div class=\"cbody\"><div class=\"bars\" id=\"bars\"></div></div></div>\n    <div class=\"card\"><div class=\"cbody\"><div>Total visitors now</div><div class=\"stat\" id=\"tot\">0</div><div style=\"margin-top:12px;color:var(--mut)\">Updates every 2 seconds from Python</div></div></div>\n  </div>\n  <div class=\"card\" style=\"margin-top:22px\"><div class=\"cbody\"><canvas id=\"line\"></canvas></div></div>\n</section>\n{% endblock %}\n{% block scripts %}\n<script>\n/* hero: rotating sentence + photo slideshow */\nconst W = ['Explore the island of paradise', 'Beaches at sunrise', 'Misty mountains', 'Wild elephants', 'Ancient culture'];\nlet wi = 0, ci = 0, dl = false;\n(function t() {\n  const w = W[wi]; $('typed').textContent = w.slice(0, ci);\n  if (!dl && ci++ === w.length) { dl = true; return setTimeout(t, 1800); }\n  if (dl && --ci === 0) { dl = false; wi = (wi + 1) % W.length; }\n  setTimeout(t, dl ? 35 : 80);\n})();\nconst S = [...document.querySelectorAll('.slide')]; let cur = 0;\nsetInterval(() => { cur = (cur + 1) % S.length; S.forEach((s, k) => s.classList.toggle('on', k === cur)); }, 4000);\nlet s = 0; setInterval(() => $('sec').textContent = ++s, 1000);\n\n/* live bar chart: click a bar to open its page */\nconst N = ['Beaches', 'Mountains', 'Wildlife', 'Culture', 'Food'], hist = [];\nconst COL = ['#047857', '#0e9f6e', '#f59e0b', '#0891b2', '#dc2626'];\nN.forEach(n => $('bars').insertAdjacentHTML('beforeend', `<div class=\"bar\" title=\"Click to open\"><div style=\"height:10px\"></div>${n}</div>`));\n$('bars').onclick = e => { const b = e.target.closest('.bar'); if (b) location.href = '/destination/' + N[[...$('bars').children].indexOf(b)].toLowerCase() + '/'; };\nconst lc = $('line'), lx = lc.getContext('2d');\nasync function upd() {\n  let v;\n  try { v = (await (await fetch('/api/live/')).json()).values; } catch { v = N.map(() => Math.floor(Math.random() * 95) + 5); }\n  const mx = Math.max(...v), sum = v.reduce((a, b) => a + b, 0);\n  [...$('bars').children].forEach((b, i) => { const d = b.firstElementChild; d.style.height = v[i] / mx * 190 + 10 + 'px'; d.style.background = COL[i]; d.textContent = v[i]; });\n  $('tot').textContent = sum; hist.push(sum); if (hist.length > 40) hist.shift();\n  lc.width = lc.clientWidth * 2; lc.height = lc.clientHeight * 2; lx.lineWidth = 5; lx.strokeStyle = '#047857'; lx.beginPath();\n  const m = Math.max(...hist), st = lc.width / 39;\n  hist.forEach((x, i) => { const px = i * st, py = lc.height - x / m * (lc.height - 20) - 10; i ? lx.lineTo(px, py) : lx.moveTo(px, py); }); lx.stroke();\n}\nupd(); setInterval(upd, 2000);\n</script>\n{% endblock %}\n",
 "blog/templates/lk/post_detail.html": "{% extends \"lk/base.html\" %}\n{% block title %}{{ post.title }} – Sri Lanka Travel{% endblock %}\n{% block content %}\n<main class=\"wrap\" style=\"max-width:820px\">\n  <a class=\"btn\" href=\"{% url 'home' %}\">← Back to stories</a>\n  <h1 style=\"margin:18px 0;color:var(--g1);font-size:clamp(2rem,6vw,3.2rem)\">{{ post.title }}</h1>\n  {% if post.image %}<img src=\"{{ post.image.url }}\" alt=\"\" style=\"width:100%;max-height:420px;object-fit:cover;border-radius:18px;margin-bottom:18px\">{% endif %}\n  <div class=\"card\"><div class=\"cbody\">{{ post.content|linebreaks }}</div></div>\n</main>\n{% endblock %}\n",
 "config/urls.py": "from django.conf import settings\nfrom django.conf.urls.static import static\nfrom django.contrib import admin\nfrom django.urls import include, path\n\nurlpatterns = [\n    path(\"admin/\", admin.site.urls),\n    path(\"\", include(\"blog.urls\")),      # sends everything else to blog/urls.py\n]\n\n# shows uploaded post images while you develop\nif settings.DEBUG:\n    urlpatterns += static(settings.MEDIA_URL, document_root=settings.MEDIA_ROOT)\n"
}

for path, text in FILES.items():
    if path.startswith("config/") and not os.path.isdir("config"):
        print("skip (no config folder):", path)
        continue
    os.makedirs(os.path.dirname(path), exist_ok=True)
    if os.path.exists(path):
        shutil.copy(path, path + ".bak")
    with open(path, "w", encoding="utf-8", newline="\n") as f:
        f.write(text)
    print("written:", path)

print()
print("DONE. Now press Ctrl+F5 in the browser (server restarts by itself).")
print("Also check config/settings.py has: STATIC_URL, MEDIA_URL, MEDIA_ROOT and APP_DIRS = True")
